/**
 * 身份与隔离契约测试：角色闸门、HMAC 验签、会话归属（用户/组隔离）、后台组过滤。
 *
 * <p>依赖 Redis（会话归属登记落 Redis sess: 键）；不可达则整体跳过，不误报失败。
 * 调试模式（未配 IW_AUTH_SECRET）下带 X-IW-* 头即按头记名，验签支路用覆写密钥的
 * IdentityService 子类单独覆盖——与生产替换点（identify 一个方法）保持同形。</p>
 *
 * @author IceWright builder
 */
@SpringBootTest
@AutoConfigureMockMvc
class IdentityIsolationTest {

    @Autowired
    private MockMvc mvc;

    @Autowired
    private SessionService sessionService;

    @Autowired
    private IdentityService identityService;

    @Autowired
    private OverviewController overviewController;

    @BeforeEach
    void requireRedis() {
        Assumptions.assumeTrue("ok".equals(sessionService.redisPing()),
            "Redis 不可达，身份隔离测试跳过");
    }

    /** Redis 登记跨轮次存续，键必须带随机后缀（与异步契约测试同一卫生纪律）。 */
    private static String uid() {
        return java.util.UUID.randomUUID().toString().substring(0, 8);
    }

    private static MockHttpServletRequest req(String user, String group, String role) {
        MockHttpServletRequest request = new MockHttpServletRequest();
        if (user != null) {
            request.addHeader("X-IW-User", user);
            request.addHeader("X-IW-Group", group);
            request.addHeader("X-IW-Role", role);
        }
        return request;
    }

    @Test
    void devModeNoHeadersMeansLocalDeveloper() {
        IdentityService.Identity identity = identityService.identify(req(null, null, null));
        assertEquals("dev-local", identity.user());
        assertEquals("developer", identity.role());
        assertTrue(identityService.devMode(), "测试环境未配置 IW_AUTH_SECRET，应为调试模式");
    }

    @Test
    void badCharsetAndUnknownRoleRejected() {
        assertEquals(400, assertThrows(ResponseStatusException.class,
            () -> identityService.identify(req("bad user/空格", "g", "customer"))).getStatusCode().value());
        assertEquals(403, assertThrows(ResponseStatusException.class,
            () -> identityService.identify(req("u", "g", "superadmin"))).getStatusCode().value());
    }

    @Test
    void signedModeValidatesHmacAndRefusesMissingHeaders() {
        IdentityService signed = new IdentityService(sessionService) {
            @Override
            protected String authSecret() {
                return "test-secret";
            }
        };
        MockHttpServletRequest ok = req("u1", "g1", "agent");
        ok.addHeader("X-IW-Sign", signed.sign("u1", "g1", "agent"));
        assertTrue(signed.identify(ok).signed());

        MockHttpServletRequest tampered = req("u1", "g1", "agent");
        tampered.addHeader("X-IW-Sign", "deadbeef");
        assertEquals(401, assertThrows(ResponseStatusException.class,
            () -> signed.identify(tampered)).getStatusCode().value());
        assertEquals(401, assertThrows(ResponseStatusException.class,
            () -> signed.identify(req("u1", "g1", "agent"))).getStatusCode().value());
        assertEquals(401, assertThrows(ResponseStatusException.class,
            () -> signed.identify(req(null, null, null))).getStatusCode().value());
    }

    @Test
    void sessionBoundToFirstOwnerOthersRejected() {
        String session = "s-jown-" + uid();
        identityService.ensureSession(new IdentityService.Identity("alice", "g1", "customer", false), session);
        assertEquals(403, assertThrows(ResponseStatusException.class, () -> identityService
            .ensureSession(new IdentityService.Identity("bob", "g1", "customer", false), session))
            .getStatusCode().value());
        assertEquals(403, assertThrows(ResponseStatusException.class, () -> identityService
            .viewable(new IdentityService.Identity("alice", "g2", "customer", false), session))
            .getStatusCode().value());
        identityService.ensureSession(
            new IdentityService.Identity("devx", "ops", "developer", false), session);
        identityService.viewable(new IdentityService.Identity("alice", "g1", "customer", false), session);
        identityService.viewable(
            new IdentityService.Identity("anyone", "g", "customer", false), "s-jnone-" + uid());
    }

    @Test
    void crossUserChatRejectedByHttpLayer() throws Exception {
        String session = "s-jcross-" + uid();
        String payload = "{\"session_id\":\"" + session + "\",\"message\":\"理赔需要哪些材料\"}";
        mvc.perform(post("/chat").contentType(MediaType.APPLICATION_JSON).content(payload)
                .header("X-IW-User", "alice").header("X-IW-Group", "g1").header("X-IW-Role", "customer"))
            .andExpect(status().isOk());
        mvc.perform(post("/chat").contentType(MediaType.APPLICATION_JSON).content(payload)
                .header("X-IW-User", "bob").header("X-IW-Group", "g1").header("X-IW-Role", "customer"))
            .andExpect(status().isForbidden());
        mvc.perform(post("/chat").contentType(MediaType.APPLICATION_JSON).content(payload)
                .header("X-IW-User", "devx").header("X-IW-Group", "ops").header("X-IW-Role", "developer"))
            .andExpect(status().isOk());
    }

    @Test
    void adminOverviewRejectsCustomerAndAgent() {
        assertEquals(403, assertThrows(ResponseStatusException.class, () -> overviewController
            .adminOverview(req("u", "g", "customer"))).getStatusCode().value());
        assertEquals(403, assertThrows(ResponseStatusException.class, () -> overviewController
            .adminOverview(req("u", "g", "agent"))).getStatusCode().value());
    }

    @Test
    void consoleGroupFilteringFollowsBusinessConsoleFlag() {
        if (!Settings.BUSINESS_CONSOLE) {
            assertEquals(404, assertThrows(ResponseStatusException.class, () -> overviewController
                .consoleSessions(req("dev", "ops", "developer"))).getStatusCode().value());
            return;
        }
        String sessionA = "s-jcg-a-" + uid();
        String sessionB = "s-jcg-b-" + uid();
        sessionService.saveSlots(sessionA, Map.of("flagged", "r1", "turns", 3));
        sessionService.putRecord("sess:" + sessionA, Map.of("user", "uA", "group", "ga"));
        sessionService.saveSlots(sessionB, Map.of("flagged", "r1", "turns", 1));
        sessionService.putRecord("sess:" + sessionB, Map.of("user", "uB", "group", "gb"));

        assertEquals(403, assertThrows(ResponseStatusException.class, () -> overviewController
            .consoleSessions(req("u", "g", "customer"))).getStatusCode().value());

        List<ConsoleSessionRow> forAgent =
            overviewController.consoleSessions(req("op1", "ga", "agent"));
        assertTrue(forAgent.stream().anyMatch(row -> row.sessionId().equals(sessionA)));
        assertTrue(forAgent.stream().noneMatch(row -> row.sessionId().equals(sessionB)),
            "agent 只见本组会话");

        List<ConsoleSessionRow> forDev =
            overviewController.consoleSessions(req("dev", "ops", "developer"));
        assertTrue(forDev.stream().anyMatch(row -> row.sessionId().equals(sessionA)
            && "uA".equals(row.user()) && "ga".equals(row.group())), "developer 见全部且行含归属");
    }
}
